function MembersForm({
  fields,
  initial,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly MembersField[];
  initial: MembersValues;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: MembersValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<MembersValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: MembersSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderMembersField(field, values, set)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

