function MembersNewInner() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const { tenant, loading: tenantLoading } = useTenant();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.members.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/members/${text(row.id)}`);
    }
  });
  if (tenantLoading) return <PaneSkeleton />;
  if (tenant === null) return <NoTenant />;
  return (
    <Pane title="New team member" actions={<Link href="/members" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>}>
      <MembersForm
        fields={MEMBERS_CREATE}
        initial={EMPTY_MEMBERS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate({ ...toMembersCreateInput(values), team_id: tenant?.id } as Input<"create">)}
      />
    </Pane>
  );
}

function MembersDetailInner() {
  const { id: rawId } = useParams<{ id: string }>();
  const id = idOf(rawId);
  const router = useRouter();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  useEffect(() => {
    setEditing(false);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.members.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["members"]["update"]) => client.members.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["members"]["delete"]) => client.members.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push("/members");
    }
  });

  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <RowError error={query.error} signIn={<Link href="/login" className={buttonVariants()}>Sign in</Link>} />;
  const row: Detail = query.data;
  void row;
  return (
    <Pane
      title={text(row.id) || "Team Member " + text(row.id)}
      actions={
        <>
          <Link href="/members" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this team member?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >


      {editing ? (
        <MembersForm
          fields={MEMBERS_UPDATE}
          initial={membersFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toMembersUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Team">{user !== null ? <Link href={`/teams/${text(row.team_id)}`} className="hover:underline">{text(row.team_id) || "—"}</Link> : text(row.team_id) || "—"}</FieldRow>
        <FieldRow label="User">{text(row.user_id) || "—"}</FieldRow>
        <FieldRow label="Role">{row.role == null ? "—" : <Badge variant="secondary">{text(row.role)}</Badge>}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        </dl>
      )}
    </Pane>
  );
}

